import numpy as np
import pandas as pd

# Define a NaTLike class with NaN year/month/day attributes (mimics pd.NaT)
class NaTLike:
    @property
    def year(self):
        return float('nan')
    @property
    def month(self):
        return float('nan')
    @property
    def day(self):
        return float('nan')
    @property
    def hour(self):
        return float('nan')
    @property
    def minute(self):
        return float('nan')
    @property
    def second(self):
        return float('nan')
    @property
    def microsecond(self):
        return float('nan')

# Test case 1: Convert pd.NaT via asarray + astype
try:
    result1 = np.asarray(pd.NaT).astype('datetime64')
    probe('pd_nat_astype', 1)  # Success
except TypeError as e:
    probe('pd_nat_astype_error', str(e))
except Exception as e:
    probe('pd_nat_astype_other_error', str(e))

# Test case 2: Convert NaTLike via asarray + astype with explicit unit
try:
    result2 = np.asarray(NaTLike(), dtype=object).astype('datetime64[ns]')
    probe('natlike_astype_ns', 1)  # Success
except TypeError as e:
    probe('natlike_astype_ns_error', str(e))
except Exception as e:
    probe('natlike_astype_ns_other_error', str(e))

# Test case 3: Direct datetime64 scalar constructor with NaTLike
try:
    result3 = np.datetime64(NaTLike(), 'ns')
    probe('datetime64_natlike_constructor', 1)  # Success
except TypeError as e:
    probe('datetime64_natlike_constructor_error', str(e))
except Exception as e:
    probe('datetime64_natlike_constructor_other_error', str(e))
